 return modalFrame(esc(f.title),f.origin,`<div class="flex mb" style="flex-wrap:wrap">${chip(f.kind==='confirmed'?'Confirmed mismatch':f.kind==='diagnostic'?'Engine diagnostic':'Judgment / evidence gap',f.kind==='confirmed'?'red':'amber')}${chip(C.areaName(f.area),'outline')}${chip(title(f.status),f.status==='resolved'?'green':'blue')}${f.blocking?chip('Blocks filing','red'):chip('Informational','outline')}</div><p style="font-size:14px;line-height:1.8">${esc(f.detail)}</p><div class="panel panel-pad mt"><h3 class="small mb">How this was surfaced</h3><p class="small muted">${esc(f.rule)}</p></div><div class="mt"><div class="detail-label">Trace to supporting evidence</div>${refs(f.refs,25)}</div>${patches.length?`<section class="panel panel-pad mt"><h3 class="small mb">${already?'Recorded adjustment':'Proposed correction · not yet applied'}</h3>${patches.map(t=>`<div class="diff"><code>${esc(t.target)}</code><del>${esc(typeof C.value(P,S,t.target)==='number'?money(C.value(P,S,t.target),2):C.value(P,S,t.target)??'Not in engine')}</del>${icon('arrow')}<ins>${esc(typeof t.value==='number'?money(t.value,2):t.value)}</ins></div>`).join('')}<div class="detail-pair mt"><div class="amount-tile"><div class="eyebrow">Estimated federal tax effect</div><strong>${signed(effect.federal)}</strong>${effect.federalPayment?`<p class="tiny muted mt">Payments change ${signed(effect.federalPayment)}</p>`:''}</div><div class="amount-tile"><div class="eyebrow">Estimated California tax effect</div><strong>${signed(effect.california)}</strong>${effect.californiaPayment?`<p class="tiny muted mt">Payments change ${signed(effect.californiaPayment)}</p>`:''}</div></div></section>`:''}${f.scenario?`<div class="mt">${button('View supplied what-if','scenario',{id:f.scenario})}</div>`:''}${f.review?`<div class="mt">${record('Recorded review disposition',f.review,true)}</div>`:''}${already?`<div class="mt">${notice('The correction is recorded, but it still needs an independent reviewer disposition. The original source and engine result remain intact.','info')}</div>`:''}`,foot);
