function referenceModal(ref,version,page,evId){if(!C.available(P,S,ref))return modalFrame('Evidence has not arrived yet.','CASE-CLOCK CONTROL',notice('This source belongs to a later event in the scripted case. Advance the season replay before relying on it.'),button('Open season replay','go-timeline',{},'primary'));
 if(ref.startsWith('attachment:')){const a=S.attachments.find(a=>a.id===ref);return modalFrame(a?esc(a.name):'Attachment unavailable','ATTACHED EVIDENCE',a?record('Attachment record',{...a,data:'[binary data retained in workspace]'},true):notice('This attachment is not visible to your role.'),a?button('Download attachment','attachment-download',{id:a.id}):'');}
 if(ref.startsWith('manual:')){const l=C.effectiveLines(P,S,version).find(l=>l.key===ref);if(l)return lineModal(l,version);}
 const resolved=C.resolveRef(P,ref,version);
 if(resolved.type==='line')return lineModal(resolved.item,version);
 if(resolved.type==='document')return sourceModal(resolved.item,page||resolved.page||1,evId);
 if(resolved.type==='value')return sourceModal(resolved.document,resolved.item.page,resolved.item.id);
 if(resolved.type==='evidence')return modalFrame(esc(ref),'CLIENT / COLLEAGUE EVIDENCE',record('Original evidence',resolved.item,true)+`<div class="mt">${button('Create cross-link','link',{from:ref})}</div>`);
 if(resolved.type==='record')return modalFrame(esc(ref),'REFERENCED RECORD',resolved.item===undefined?notice('The packet contains this reference but its target could not be resolved. Preserve the gap and raise a review note.','warn'):record('Source record',resolved.item,true),button('Link to another item','link',{from:ref}));
 return modalFrame('Unresolved reference','SOURCE INTEGRITY',notice(`The reference ${esc(ref)} could not be resolved from the packet. It is not silently treated as evidence.`,'warn'),button('Create review note','new-note',{target:ref}));
}
function lineModal(line,version){const l=C.effectiveLines(P,S,version).find(l=>l.key===line.key)||line;const src=l.key.startsWith('manual:')?l.sources:C.evidence(P,l.key,version),down=C.descendants(P,l.key,version);const verified=S.verification[l.key],adjusted=S.adjustments.filter(a=>!a.undone&&a.patches.some(p=>p.target===l.key));
 return modalFrame(esc(line.label),`${line.key} · ${version} · ${line.jurisdiction}`,`<div class="detail-pair"><div class="amount-tile"><div class="eyebrow">Original engine value</div><strong>${fieldVal({...l,value:l.original??l.value})}</strong></div><div class="amount-tile highlight"><div class="eyebrow">${l.stale?'Engine value · stale dependencies':'Current review value'}</div><strong>${fieldVal(l)}</strong><div class="tiny muted">${l.direct?'Explicit human override':l.derived?'Exact supported arithmetic bridge':l.stale?'Not recomputed':'No adjustment recorded'}</div></div></div>${l.stale?`<div class="mt">${notice('An input changed but this tax computation is not implemented here. The displayed engine value is stale. The estimated tax impact is separately recorded in the adjustment ledger.','warn')}</div>`:''}<div class="mt"><div class="detail-label">Calculation pathway</div><div class="flow-node"><div class="between"><span class="small"><strong>${esc(l.rule)}</strong></span>${chip('Supplied engine rule','outline')}</div><p class="small muted mt" style="margin-top:8px">${esc(P.engine_reference.rules[l.rule]||'No detailed rule description supplied.')}</p>${l.note?`<p class="small muted mt">${esc(l.note)}</p>`:''}</div>${l.inputs?.length?`<div class="flow-arrow">${icon('down')}</div><div class="flow-node"><div class="detail-label">Inputs · select any to inspect its calculation</div><div class="refs">${l.inputs.map(refLink).join('')}</div></div>`:''}<div class="flow-arrow">${icon('down')}</div><div class="panel panel-pad"><div class="detail-label">Underlying evidence · ${src.length} references</div>${refs(src,60)}${!src.length?notice('No source reference was supplied for this line. Review the rule and document the evidence gap.','warn'):''}</div></div>${down.length?`<div class="mt"><div class="detail-label">Where this number goes · ${down.length} downstream lines</div>${refs(down,24)}</div>`:''}${verified?`<div class="mt">${record('Verification record',verified,true)}</div>`:''}${adjusted.length?`<div class="mt">${record('Adjustment history',adjusted)}</div>`:''}${S.links.some(x=>x.from===l.key||x.to===l.key)?`<div class="mt">${refs(S.links.filter(x=>x.from===l.key||x.to===l.key).flatMap(x=>[x.from,x.to]))}</div>`:''}`,button('Verify this value','verify',{id:l.key})+button('Record adjustment','manual-adjust',{target:l.key},'primary')+button('Add note','new-note',{target:l.key,area:C.areaOf(l.key)}));
}
// Highlight actual printed text, not the pipeline's claimed value or synthetic box.
function printedHighlight(text,e){if(!e)return {html:esc(text),matched:false};let start=0,end=text.length,field=e.field||'';
 const lot=field.match(/^((?:RSU|ESPP)-\d+|[NMCX]\d+)_/);if(lot){const needle=lot[1].replace(/[.*+?^${}()|[\]\\]/g,'\\$&'),m=new RegExp('\\b'+needle+'(?:\\s|:)','i').exec(text);if(m){start=m.index;const rest=text.slice(start);const split=rest.search(/;|\. Lot /);end=split>=0?start+split:text.length;}}
 const scope=text.slice(start,end);let m;
 const box=field.match(/^box(\d+[a-z]?)/i);
 if(box){m=new RegExp('Box\\s+'+box[1]+'(?!\\d)[^;]*(?=;|$)','i').exec(scope);}
 else if(/ein|tax_id/i.test(field))m=/(?:Tax ID|EIN|TIN)\s*[:#]?\s*[\d-]+/i.exec(scope);
 else if(/ssn/i.test(field))m=/(?:SSN|Social Security card:?)[^;.]*/i.exec(scope);
 else if(/proceeds/i.test(field))m=/proceeds\s+[\d,.]+/i.exec(scope);
 else if(/basis|cost/i.test(field)&&lot)m=/(?:adjusted\s+)?(?:cost\s+)?basis\s*[:=]?\s*(?:\([^)]*\)|[\d,.]+|not reported)|cost\s+[\d,.]+/i.exec(scope);
 else if(/acq/i.test(field)&&lot)m=/acquired\s+[\d/-]+/i.exec(scope);
 else if(/sold/i.test(field)&&lot)m=/sold\s+[\d/-]+/i.exec(scope);
 else if(/wash/i.test(field)&&lot)m=/wash(?: sale loss disallowed)?\s+[\d,.]+/i.exec(scope);
 else if(/page.*total|total.*page/i.test(field))m=/Page total [\d,]+ miles/i.exec(scope);
 if(m){const a=start+m.index,b=a+m[0].length;return {html:esc(text.slice(0,a))+'<mark>'+esc(text.slice(a,b))+'</mark>'+esc(text.slice(b)),matched:true,printed:m[0]};}
 // Exact textual fallback within the already isolated lot, when possible.
 let candidates=[e.text_as_read,typeof e.value==='number'?e.value.toLocaleString('en-US',{minimumFractionDigits:e.value_type==='money'?2:0,maximumFractionDigits:5}):e.value].filter(x=>typeof x==='string'&&x.length>2&&!x.includes('restricted'));
 for(const c of candidates){const n=scope.indexOf(c);if(n>=0&&scope.indexOf(c,n+c.length)<0){const a=start+n,b=a+c.length;return {html:esc(text.slice(0,a))+'<mark>'+esc(text.slice(a,b))+'</mark>'+esc(text.slice(b)),matched:true,printed:c};}}
 return {html:esc(text),matched:false};
}
function sourceModal(doc,page=1,evId){if(!doc)return modalFrame('Document not found','SOURCE GAP',notice('The packet reference points to a missing document.','warn'));
 if(!C.available(P,S,doc.id))return referenceModal(doc.id,S.currentVersion);
 const selected=P.extracted_values.find(e=>e.id===evId),pg=doc.pages.find(p=>p.page===Number(page))||doc.pages[0],fields=P.extracted_values.filter(e=>e.document_id===doc.id&&e.page===pg.page),h=printedHighlight(pg.printed_content,selected);
 const currentV=C.indexes(P,S.currentVersion).v,docEV=new Set(P.extracted_values.filter(e=>e.document_id===doc.id).map(e=>e.id));const direct=currentV.lines.filter(l=>(l.sources||[]).some(r=>docEV.has(r)||r.startsWith('doc:'+doc.id+'#'))),down=[...new Set(direct.flatMap(l=>[l.key,...C.descendants(P,l.key,S.currentVersion)]))];
 const foot=button('Account for document','single-doc-account',{id:doc.id})+(selected?button('Verify selected field','verify',{id:selected.id},'primary'):'')+button('Attach supporting file','attach',{target:doc.id});
 const reviewer=S.documentReviews[doc.id];
 return modalFrame(esc(doc.title),`${doc.id} / SOURCE DOCUMENT`, `<div class="between mb"><div class="flex" style="flex-wrap:wrap">${chip('Simulated source','blue')}${chip(doc.extraction.status==='extracted'?'Extracted':title(doc.extraction.status),doc.extraction.status==='extracted'?'outline':'amber')}${reviewer?chip(title(reviewer.status),'green'):chip('Not yet accounted for','outline')}</div><div class="flex">${button('Previous','source-page',{id:doc.id,page:Math.max(1,pg.page-1)},'ghost small')}${select('source-page-select',doc.pages.map(p=>[String(p.page),`Page ${p.page} of ${doc.page_count}`]),String(pg.page),`data-doc="${doc.id}"`)}${button('Next','source-page',{id:doc.id,page:Math.min(doc.pages.at(-1).page,pg.page+1)},'ghost small')}</div></div>${notice('This page is rendered from documents.pages.printed_content. It is not an original image. Pipeline values are shown separately, and source highlights refer to the printed text—not synthetic coordinates.','info')}<div class="source-layout mt"><div><article class="paper"><div class="paper-kicker">SIMULATED DOCUMENT / SOURCE-TRUTH REPRESENTATION</div><h3>${esc(doc.issuer)}</h3><div class="tiny muted" style="font-family:var(--font)">${esc(doc.document_type)} · Tax year ${doc.tax_year}</div><div class="paper-body">${h.html}</div><div class="paper-footer"><span>${esc(doc.file_name)}</span><span>${pg.page} / ${doc.page_count}</span></div></article>${selected&&!h.matched?`<div class="mt">${notice('The exact field could not be automatically anchored in this narrative representation. The originating page and field label are retained, but no precise highlight or verification is claimed. Inspect the printed text before signing off.','warn')}</div>`:''}${reviewer?`<div class="mt">${record('Document review disposition',reviewer)}</div>`:''}</div><div class="stack">${selected?`<section class="panel">${sectionHead('Pipeline read · not source truth')}<div class="panel-pad"><div class="eyebrow">${esc(selected.id)}</div><h3 class="small mt" style="margin-top:8px">${esc(selected.label)}</h3><div class="number" style="font-size:23px;margin-top:9px;overflow-wrap:anywhere">${esc(typeof selected.value==='number'?selected.value_type==='money'?money(selected.value,2):number(selected.value):selected.value)}</div><div class="mt">${chip(number(selected.confidence*100,0)+'% extraction confidence',selected.confidence<.8?'amber':'outline')}</div>${C.override(S,selected.id)?`<div class="notice mt">Reviewed value: <strong>${esc(C.override(S,selected.id).value)}</strong></div>`:''}${h.printed?`<p class="tiny muted mt">Highlighted printed text: <strong>${esc(h.printed)}</strong></p>`:''}</div></section>`:''}<section class="panel">${sectionHead('Fields on this page',fields.length+' extracted values')}<div style="max-height:370px;overflow:auto">${fields.slice(0,U.sourceFields).map(e=>`<div class="field-row ${e.id===evId?'active':''}" data-action="ref" data-ref="${e.id}" role="button" tabindex="0"><span class="mono muted">${e.id}</span><div>${esc(e.label)}</div><strong>${esc(typeof e.value==='number'?e.value_type==='money'?money(e.value,2):number(e.value):e.value)}</strong><span class="muted">Confidence ${number(e.confidence*100)}%</span></div>`).join('')||empty('No extracted fields','The full printed content is still available as evidence.','doc')}</div>${fields.length>U.sourceFields?`<div class="panel-pad" style="padding:10px">${button('Show more fields','source-more',{},'small full')}</div>`:''}</section><section class="panel">${sectionHead('Reverse trace',`${direct.length} direct uses · ${down.length} affected lines`)}<div class="panel-pad">${refs(direct.map(l=>l.key),18)}${!direct.length?`<p class="tiny muted">No direct return-line source links. A human must account for this as supporting evidence, reference, duplicate, superseded or not applicable.</p>`:''}<div class="mt">${refs(down.filter(k=>!direct.some(l=>l.key===k)),12)}</div></div></section></div></div>`,foot,true);
}
