function searchModal(){return modalFrame('Find the evidence you need.','GLOBAL SEARCH',`<input id="global-search" class="full" placeholder="Try: mileage, SchC.44a, D23, payment or a client question" autocomplete="off" aria-label="Global search"><div id="search-results" class="panel mt">${empty('Search across the packet','Documents, return lines, extracted fields and client messages.','search')}</div><div class="keyboard-help">Esc closes the panel. Click a result to follow its source.</div>`);}
function searchResults(query){if(!query.trim())return empty('Search across the packet','Type a document, number, topic or line key.','search');const q=query.toLowerCase();const hits=[];
 for(const d of P.documents)if((d.id+' '+d.title+' '+d.issuer+' '+d.pages.map(p=>p.printed_content).join(' ')).toLowerCase().includes(q))hits.push({ref:d.id,title:d.title,sub:d.id+' · Document · '+d.page_count+' pages',icon:'doc'});
 for(const l of C.indexes(P,S.currentVersion).v.lines)if((l.key+' '+l.label).toLowerCase().includes(q))hits.push({ref:l.key,title:l.label,sub:l.key+' · '+String(l.value),icon:'layers'});
 for(const m of [...P.client.messages,...P.client.questionnaire,...P.client.call_notes])if(JSON.stringify(m).toLowerCase().includes(q))hits.push({ref:m.id,title:m.question||m.text||'Client call notes',sub:m.id+' · Client evidence',icon:'mail'});
 for(const e of P.extracted_values)if(e.id.toLowerCase()===q||e.field.toLowerCase().includes(q))hits.push({ref:e.id,title:e.label,sub:e.id+' · '+e.document_id+' · '+String(e.value),icon:'doc'});
 return hits.length?hits.slice(0,35).map(h=>`<button class="search-result" data-action="ref" data-ref="${esc(h.ref)}">${icon(h.icon)}<div><strong>${esc(h.title)}</strong><span class="muted tiny">${esc(h.sub)}</span></div></button>`).join('')+`<div class="keyboard-help">Showing ${Math.min(35,hits.length)} of ${hits.length} results. Refine your query for more specific matches.</div>`:empty('No matches','Try a shorter phrase, a form code or a document ID.','search');}
