  body=`${n?`<div class="notice mb">${esc(n.text)}</div>`:''}${rowField('Message',`<textarea name="text" required minlength="3" placeholder="State the question, evidence gap or review concern.">${esc(m.text||'')}</textarea>`)}${form!=='reply'?`<div class="form-grid">${rowField('Type',select('note-kind',[['review','Review note'],['question','Question']],'review','name="kind"'))}${rowField('Area',areaSelect(m.area||C.areaOf(m.target||'')))}</div><div class="form-grid">${rowField('Assign to',select('assigned-to',[['','Unassigned'],...PEOPLE.map(p=>[p.id,p.name])],'','name="assignedTo"'))}${rowField('Due date',`<input name="due" type="date">`)}</div>${rowField('Linked target',`<input name="target" value="${esc(m.target||'')}" placeholder="Return line, finding or document ID">`)}<div class="form-field"><label><input name="blocking" type="checkbox" checked> Blocks filing until resolved</label><label style="margin-top:10px"><input name="clientVisible" type="checkbox"> Share with the client</label></div>`:''}${rowField('Supporting references (optional)',`<input name="refs" value="${esc(m.refs||'')}" placeholder="D23, call-01">`)}`;
